{
  "findings": [
    {
      "title": "Inconsistent sample size calculation: 69 subjects for 90% power vs 100 enrolled",
      "page": 80,
      "quote": "A sample size of 69 subjects achieves at least 90% power to detect a difference of 13% using a 2-sided exact test with a significance level of 0.05, assuming that the null hypothesis for ORR is 7% (Hodi-2016; Ribas-2018), and the study ORR is 20%. The sample size was increased to 100 subjects to adjust for an early discontinuation rate of 15% and to allow for a robust assessment of safety.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 8.2.3 for SAE definition",
      "page": 74,
      "quote": "of AEs and SAEs (as defined in Section 8.2.3.)",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 8.2.3 for AE outcome classification",
      "page": 75,
      "quote": "8.2.3. Classification of Adverse Event Outcome",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 8.2.3 for SAE reporting",
      "page": 77,
      "quote": "following the same reporting process outlined in Section 8.3.1.)",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of TEAE collection period: 100 days vs 30 days for concomitant meds",
      "page": 76,
      "quote": "Treatment-emergent adverse events observed until 100 days after the last dose of study treatment (both CMP-001 and nivolumab) or until an alternative cancer treatment is initiated, whichever occurs first, are to be recorded on the AE page of the eCRF.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent reporting of SAEs: 'within 24 hours' vs 'promptly'",
      "page": 77,
      "quote": "the event and any known details must be reported promptly to the Sponsor or its representatives.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of ITT Analysis Set: 'receive at least 1 dose' vs 'enrolled'",
      "page": 80,
      "quote": "A subject is enrolled in the study when they have received the first dose of study treatment.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of PK Analysis Set: 'evaluable samples at Baseline' vs 'measurable sample at Baseline'",
      "page": 81,
      "quote": "The PK Analysis Set is defined as all subjects who receive CMP-001 and have evaluable samples at Baseline and after CMP-001 injection.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of DOR: 'first date that recurrence or PD' vs 'first date that recurrent disease'",
      "page": 83,
      "quote": "until the first date that recurrence or PD is objectively documented (taking as reference for PD the smallest measurements recorded on study). The duration of overall CR is measured from the time measurement criteria are first met for CR until the first date that recurrent disease is objectively documented.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of PFS: 'time from first dose' vs 'time from randomization'",
      "page": 83,
      "quote": "Progression-free survival is defined as the time from first dose of study treatment to the date of documented PD based on RECIST v1.1 by BICR or death from any cause, whichever occurs first.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of OS: 'time from first dose' vs 'time from randomization'",
      "page": 83,
      "quote": "Overall survival will be calculated as the time from first dose of study treatment to the date of death due to any cause.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of TEAE: 'started or worsened' vs 'observed'",
      "page": 73,
      "quote": "A TEAE is defined as an AE that started or worsened in severity on or after the date that study treatment was first administered (W1D1) until 100 days after the last dose of study treatment or until an alternative cancer treatment is initiated, whichever occurs first",
      "severity": "minor"
    }
  ]
}
